if __name__ == "__main__":
    only = sys.argv[1:]
    if only and not any(o in m.name for m in M for o in only):
        print(f"no mutant name contains any of {only}; nothing was run", file=sys.stderr)
        sys.exit(2)
    first_lines: dict[str, str] = {}

    def show(row):
        name, v, test_id, good = row
        print(
            f"{'ok ' if good else 'BAD'} {v:12} {name}  [{test_id.split('::')[-1][:60]}]",
            flush=True,
        )
        if not good:
            print("      first line:", first_lines.get(name, "")[:150], flush=True)

    res = run_mutants(
        ROOT,
        M,
        [
            TEST,
            TRACE,
            "tests/test_q8a_live_overrides.py",
            "tests/test_q8a1_b13_fixes.py",
            "tests/test_q8a1_b14_fixes.py",
            "tests/test_q8a1_b15_fixes.py",
            "tests/test_q8a1_b16_fixes.py",
            "tests/test_q8a1_b17_fixes.py",
            "tests/test_q8a1_b18_fixes.py",
            "tests/_mutant_check.py",
            "tests/test_changelog_claims.py",
            "tests/test_guard_reasons.py",
        ],
        extra_dirs=("tests", "tools", "demos", "docs"),
        only=only,
        on_result=show,
        first_lines=first_lines,
    )
    bad = [n for n, _, _, g in res if not g]
    print(f"{len(res) - len(bad)} of {len(res)} good; problems: {bad}")
    sys.exit(1 if bad else 0)
